/**
 * DIAMOND-PROTECT :: Command Centre API (bank fraud analyst console).
 *
 * Reads only synthetic demo data generated by this prototype.
 */

import { v } from "convex/values";
import { mutation, query } from "./_generated/server";
import type { MutationCtx, QueryCtx } from "./_generated/server";
import {
  DEFAULT_CONFIG,
  RULE_CATALOGUE,
  clamp,
  type RuleConfig,
} from "./lib/types";
import { sizeForVolume, topSuspiciousClusters } from "./lib/mulenet";
import { nonceFor } from "./lib/generator";

async function loadSettingsRow(ctx: QueryCtx | MutationCtx) {
  try {
    return await ctx.db
      .query("settings")
      .withIndex("by_key", (q) => q.eq("key", "global"))
      .unique();
  } catch {
    return null;
  }
}

export const metrics = query({
  args: { feedSize: v.optional(v.number()) },
  handler: async (ctx, args) => {
    try {
      const row = await ctx.db
        .query("dashMetrics")
        .withIndex("by_key", (q) => q.eq("key", "global"))
        .unique();
      const seedState = await ctx.db
        .query("systemMeta")
        .withIndex("by_key", (q) => q.eq("key", "seed"))
        .unique();
      const feed = await ctx.db
        .query("transactions")
        .withIndex("by_timestamp")
        .order("desc")
        .take(clamp(args.feedSize ?? 24, 5, 60));
      const caseRows = await ctx.db.query("fraudCases").take(200);

      const liveActiveCases = caseRows.filter(
        (entry) =>
          entry.status === "NEW" ||
          entry.status === "INVESTIGATING" ||
          entry.status === "ESCALATED",
      ).length;

      const openCases = caseRows.reduce<Record<string, number>>((acc, entry) => {
        acc[entry.status] = (acc[entry.status] ?? 0) + 1;
        return acc;
      }, {});

      return {
        ok: true,
        seeded: row !== null,
        isSeeding: Boolean(seedState?.isSeeding),
        message: seedState?.lastMessage ?? "",
        metrics: row
          ? { ...row, activeCases: liveActiveCases, caseBreakdown: openCases }
          : null,
        feed: feed.map((txn) => ({
          txnId: txn.txnId,
          userName: txn.userName,
          beneficiaryName: txn.beneficiaryName,
          beneficiaryUpiId: txn.beneficiaryUpiId,
          amount: txn.amount,
          timestamp: txn.timestamp,
          diamondTrustScore: txn.diamondTrustScore,
          riskCategory: txn.riskCategory,
          decision: txn.decision,
          qrStatus: txn.qrStatus,
          fraudPattern: txn.fraudPattern,
          isFraudLabel: txn.isFraudLabel,
          topReason: txn.reasons[0] ?? "",
        })),
        alerts: feed
          .filter((txn) => txn.diamondTrustScore < 55)
          .slice(0, 8)
          .map((txn) => ({
            txnId: txn.txnId,
            severity: txn.diamondTrustScore < 25 ? "CRITICAL" : "HIGH",
            title: `${txn.beneficiaryName} · ₹${txn.amount}`,
            detail: txn.reasons[0] ?? "High-risk payment intercepted before settlement.",
            at: txn.timestamp,
            score: txn.diamondTrustScore,
          })),
      };
    } catch {
      return {
        ok: false,
        seeded: false,
        isSeeding: false,
        message: "Command Centre data unavailable.",
        metrics: null,
        feed: [],
        alerts: [],
      };
    }
  },
});

export const mulenet = query({
  args: {
    community: v.optional(v.number()),
    status: v.optional(v.string()),
    minRisk: v.optional(v.number()),
    includeNormal: v.optional(v.boolean()),
    maxNodes: v.optional(v.number()),
  },
  handler: async (ctx, args) => {
    try {
      const accounts = await ctx.db.query("accounts").take(700);
      const suspiciousEdges = await ctx.db
        .query("graphEdges")
        .withIndex("by_suspicious", (q) => q.eq("suspicious", true))
        .take(600);
      const normalEdges = await ctx.db
        .query("graphEdges")
        .withIndex("by_suspicious", (q) => q.eq("suspicious", false))
        .take(240);
      const edges = [...suspiciousEdges, ...normalEdges];

      const minRisk = args.minRisk ?? 0;
      const includeNormal = args.includeNormal ?? true;
      const maxNodes = clamp(args.maxNodes ?? 260, 20, 500);

      let filteredAccounts = accounts.filter((account) => account.riskScore >= minRisk);
      if (args.status) {
        filteredAccounts = filteredAccounts.filter((account) => account.status === args.status);
      }
      if (args.community !== undefined && args.community !== null) {
        filteredAccounts = filteredAccounts.filter(
          (account) => (account.fraudCluster ?? -1) === args.community,
        );
      }
      if (!includeNormal) {
        filteredAccounts = filteredAccounts.filter(
          (account) => (account.fraudCluster ?? -1) >= 0 || account.riskScore >= 55,
        );
      }
      // Cluster members are always kept so the fraud rings stay complete;
      // the remaining budget then goes to the highest-risk accounts.
      filteredAccounts = [...filteredAccounts]
        .sort((a, b) => {
          const aCluster = (a.fraudCluster ?? -1) >= 0 ? 1 : 0;
          const bCluster = (b.fraudCluster ?? -1) >= 0 ? 1 : 0;
          if (aCluster !== bCluster) return bCluster - aCluster;
          return b.riskScore - a.riskScore;
        })
        .slice(0, maxNodes);

      const visible = new Set(filteredAccounts.map((account) => account.accountId));
      const visibleEdges = edges.filter(
        (edge) => visible.has(edge.source) && visible.has(edge.target),
      );

      const nodes = filteredAccounts.map((account) => ({
        id: account.accountId,
        name: account.name,
        upiId: account.upiId,
        kind: account.kind,
        risk: Math.round(account.riskScore),
        status: account.status,
        isMuleSuspect: account.isMuleSuspect,
        clusterRole: account.clusterRole ?? "NONE",
        fraudCluster: account.fraudCluster ?? -1,
        fraudClusterSize: account.fraudClusterSize ?? 0,
        fraudClusterReach: account.fraudClusterReach ?? 0,
        fraudClusterValue: account.fraudClusterValue ?? 0,
        fraudClusterMules: account.fraudClusterMules ?? 0,
        size: sizeForVolume(account.totalReceived + account.totalSent),
        inDegree: account.inDegree,
        outDegree: account.outDegree,
        totalReceived: account.totalReceived,
        totalSent: account.totalSent,
        outflowRatio: account.outflowRatio,
        uniqueSenders: account.uniqueSenders,
        uniqueReceivers: account.uniqueReceivers,
        avgReceiveToSendSec: account.avgReceiveToSendSec,
        clustering: account.clustering,
        community: account.fraudCluster ?? account.community,
        accountAgeDays: account.accountAgeDays,
        city: account.city ?? "",
        flaggedReasons: account.flaggedReasons,
      }));

      const clusters = topSuspiciousClusters(
        nodes.map((node) => ({
          ...node,
          flaggedReasons: node.flaggedReasons,
        })),
        12,
      );

      const communities = [...new Set(accounts.map((account) => account.fraudCluster ?? -1))]
        .filter((cluster) => cluster >= 0)
        .sort((a, b) => a - b)
        .map((cluster) => ({ community: cluster, label: `C${cluster}` }))
        .map((entry) => ({
          ...entry,
          size: accounts.filter((account) => (account.fraudCluster ?? -1) === entry.community)
            .length,
          mules: accounts.filter(
            (account) =>
              (account.fraudCluster ?? -1) === entry.community && account.isMuleSuspect,
          ).length,
        }));

      return {
        ok: true,
        nodes,
        edges: visibleEdges.map((edge) => ({
          source: edge.source,
          target: edge.target,
          sourceName: edge.sourceName,
          targetName: edge.targetName,
          amount: edge.amount,
          risk: edge.risk,
          timestamp: edge.timestamp,
          fraudLabel: edge.fraudLabel,
          suspicious: edge.suspicious,
        })),
        clusters,
        communities,
        totals: {
          accounts: accounts.length,
          visible: nodes.length,
          muleSuspects: accounts.filter((account) => account.isMuleSuspect).length,
          blocked: accounts.filter((account) => account.status === "BLOCKED").length,
          underReview: accounts.filter((account) => account.status === "UNDER_REVIEW").length,
        },
        legend: {
          statuses: ["NORMAL", "SUSPICIOUS", "MULE_SUSPECT", "BLOCKED", "UNDER_REVIEW", "CLEARED"],
        },
      };
    } catch {
      return {
        ok: false,
        nodes: [],
        edges: [],
        clusters: [],
        communities: [],
        totals: { accounts: 0, visible: 0, muleSuspects: 0, blocked: 0, underReview: 0 },
        legend: { statuses: [] as string[] },
      };
    }
  },
});

export const cases = query({
  args: {
    status: v.optional(v.string()),
    priority: v.optional(v.string()),
    search: v.optional(v.string()),
    assignedTo: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    try {
      const rows = await ctx.db.query("fraudCases").take(200);
      const search = (args.search ?? "").trim().toLowerCase();
      const filtered = rows
        .filter((row) => (args.status ? row.status === args.status : true))
        .filter((row) => (args.priority ? row.priority === args.priority : true))
        .filter((row) => (args.assignedTo ? row.assignedTo === args.assignedTo : true))
        .filter((row) =>
          search
            ? row.caseId.toLowerCase().includes(search) ||
              row.txnId.toLowerCase().includes(search) ||
              row.reportedBy.toLowerCase().includes(search) ||
              (row.beneficiaryUpiId ?? "").toLowerCase().includes(search) ||
              row.reason.toLowerCase().includes(search)
            : true,
        )
        .sort((a, b) => b.createdAt - a.createdAt);

      const breakdown = rows.reduce<Record<string, number>>((acc, row) => {
        acc[row.status] = (acc[row.status] ?? 0) + 1;
        return acc;
      }, {});

      const analysts = [...new Set(rows.map((row) => row.assignedTo).filter(Boolean))] as string[];

      return { ok: true, rows: filtered, all: rows.length, breakdown, analysts };
    } catch {
      return { ok: false, rows: [], all: 0, breakdown: {}, analysts: [] as string[] };
    }
  },
});

export const auditLogs = query({
  args: { limit: v.optional(v.number()), entityId: v.optional(v.string()) },
  handler: async (ctx, args) => {
    try {
      if (args.entityId) {
        return {
          ok: true,
          rows: await ctx.db
            .query("auditLogs")
            .withIndex("by_entityId", (q) => q.eq("entityId", args.entityId!))
            .take(clamp(args.limit ?? 40, 1, 100)),
        };
      }
      const rows = await ctx.db
        .query("auditLogs")
        .withIndex("by_timestamp")
        .order("desc")
        .take(clamp(args.limit ?? 40, 1, 120));
      return { ok: true, rows };
    } catch {
      return { ok: false, rows: [] };
    }
  },
});

export const settings = query({
  args: {},
  handler: async (ctx) => {
    try {
      const row = await loadSettingsRow(ctx);
      const model = await ctx.db
        .query("modelArtifacts")
        .withIndex("by_key", (q) => q.eq("key", "global"))
        .unique();
      const config: RuleConfig = row
        ? {
            highRiskThreshold: row.highRiskThreshold,
            mlThreshold: row.mlThreshold,
            newBeneficiaryWindowHours: row.newBeneficiaryWindowHours,
            rapidTransactionWindowMin: row.rapidTransactionWindowMin,
            rapidForwardingThreshold: row.rapidForwardingThreshold,
            graphSensitivity: row.graphSensitivity,
            highAmountThreshold: row.highAmountThreshold,
            ruleToggles:
              (row.ruleToggles as Record<string, boolean>) ?? DEFAULT_CONFIG.ruleToggles,
            qrValidityMinutes: row.qrValidityMinutes,
          }
        : DEFAULT_CONFIG;
      return {
        ok: true,
        config,
        catalogue: RULE_CATALOGUE,
        model: model
          ? {
              modelType: model.modelType,
              trainedAt: model.trainedAt,
              trainSize: model.trainSize,
              testSize: model.testSize,
              positiveRate: model.positiveRate,
              metrics: model.metrics,
              features: model.features,
              trainingLog: model.trainingLog,
            }
          : null,
      };
    } catch {
      return { ok: false, config: DEFAULT_CONFIG, catalogue: RULE_CATALOGUE, model: null };
    }
  },
});

export const updateSettings = mutation({
  args: {
    highRiskThreshold: v.optional(v.number()),
    mlThreshold: v.optional(v.number()),
    newBeneficiaryWindowHours: v.optional(v.number()),
    rapidTransactionWindowMin: v.optional(v.number()),
    rapidForwardingThreshold: v.optional(v.number()),
    graphSensitivity: v.optional(v.number()),
    highAmountThreshold: v.optional(v.number()),
    qrValidityMinutes: v.optional(v.number()),
    ruleToggles: v.optional(v.any()),
    actor: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    try {
      const existing = await loadSettingsRow(ctx);
      const next = {
        highRiskThreshold: clamp(args.highRiskThreshold ?? existing?.highRiskThreshold ?? DEFAULT_CONFIG.highRiskThreshold, 1, 99),
        mlThreshold: clamp(args.mlThreshold ?? existing?.mlThreshold ?? DEFAULT_CONFIG.mlThreshold, 0.05, 0.99),
        newBeneficiaryWindowHours: clamp(args.newBeneficiaryWindowHours ?? existing?.newBeneficiaryWindowHours ?? DEFAULT_CONFIG.newBeneficiaryWindowHours, 1, 168),
        rapidTransactionWindowMin: clamp(args.rapidTransactionWindowMin ?? existing?.rapidTransactionWindowMin ?? DEFAULT_CONFIG.rapidTransactionWindowMin, 1, 120),
        rapidForwardingThreshold: clamp(args.rapidForwardingThreshold ?? existing?.rapidForwardingThreshold ?? DEFAULT_CONFIG.rapidForwardingThreshold, 0.1, 1),
        graphSensitivity: clamp(args.graphSensitivity ?? existing?.graphSensitivity ?? DEFAULT_CONFIG.graphSensitivity, 0, 2),
        highAmountThreshold: clamp(args.highAmountThreshold ?? existing?.highAmountThreshold ?? DEFAULT_CONFIG.highAmountThreshold, 500, 1000000),
        qrValidityMinutes: clamp(args.qrValidityMinutes ?? existing?.qrValidityMinutes ?? DEFAULT_CONFIG.qrValidityMinutes, 1, 1440),
        ruleToggles:
          (args.ruleToggles as Record<string, boolean> | undefined) ??
          (existing?.ruleToggles as Record<string, boolean>) ??
          DEFAULT_CONFIG.ruleToggles,
        updatedAt: Date.now(),
        updatedBy: args.actor ?? "analyst",
      };

      if (existing) {
        await ctx.db.patch(existing._id, next);
      } else {
        await ctx.db.insert("settings", { key: "global", ...next });
      }

      await ctx.db.insert("auditLogs", {
        logId: `LOG-${nonceFor(["settings", Date.now()]).slice(0, 10)}`,
        actor: next.updatedBy,
        action: "RULES_UPDATED",
        entityType: "settings",
        entityId: "global",
        timestamp: Date.now(),
        details: `Thresholds updated: block < ${next.highRiskThreshold}, high-value ≥ ₹${next.highAmountThreshold}, graph sensitivity ${next.graphSensitivity}. Applies to every future scoring call.`,
      });

      return { ok: true, config: next };
    } catch (error) {
      return {
        ok: false,
        config: null,
        error: error instanceof Error ? error.message : "Could not save settings.",
      };
    }
  },
});

export const updateCase = mutation({
  args: {
    caseId: v.string(),
    status: v.optional(v.string()),
    assignedTo: v.optional(v.string()),
    note: v.optional(v.string()),
    priority: v.optional(v.string()),
    actor: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    try {
      const row = await ctx.db
        .query("fraudCases")
        .withIndex("by_caseId", (q) => q.eq("caseId", args.caseId))
        .unique();
      if (!row) return { ok: false, error: `Case ${args.caseId} not found.` };

      const allowed = ["NEW", "INVESTIGATING", "ESCALATED", "RESOLVED", "FALSE_POSITIVE"];
      const status = (
        args.status && allowed.includes(args.status) ? args.status : row.status
      ) as typeof row.status;
      const priority = (
        args.priority && ["LOW", "MEDIUM", "HIGH", "CRITICAL"].includes(args.priority)
          ? args.priority
          : row.priority
      ) as typeof row.priority;
      const assignedTo = args.assignedTo?.trim() || row.assignedTo;
      const note = (args.note ?? "").trim();
      const now = Date.now();

      const timeline = [...row.timeline];
      if (status !== row.status) {
        timeline.push({
          at: now,
          actor: args.actor ?? assignedTo ?? "analyst",
          action: status,
          note: note || `Status changed from ${row.status} to ${status}.`,
        });
      } else if (note) {
        timeline.push({
          at: now,
          actor: args.actor ?? assignedTo ?? "analyst",
          action: "NOTE",
          note,
        });
      } else if (assignedTo && assignedTo !== row.assignedTo) {
        timeline.push({
          at: now,
          actor: args.actor ?? "analyst",
          action: "ASSIGNED",
          note: `Assigned to ${assignedTo}.`,
        });
      }

      await ctx.db.patch(row._id, {
        status,
        priority,
        assignedTo,
        analystNotes: note ? `${row.analystNotes ? `${row.analystNotes}\n` : ""}${note}` : row.analystNotes,
        updatedAt: now,
        resolvedAt:
          status === "RESOLVED" || status === "FALSE_POSITIVE" ? now : row.resolvedAt,
        timeline,
      });

      await ctx.db.insert("auditLogs", {
        logId: `LOG-${nonceFor(["case", args.caseId, now]).slice(0, 10)}`,
        actor: args.actor ?? assignedTo ?? "analyst",
        action: `CASE_${status}`,
        entityType: "fraud_case",
        entityId: args.caseId,
        timestamp: now,
        details:
          note ||
          `Case ${args.caseId} moved to ${status}${assignedTo ? ` and assigned to ${assignedTo}` : ""}.`,
      });

      return { ok: true, error: null, status, assignedTo };
    } catch (error) {
      return {
        ok: false,
        error: error instanceof Error ? error.message : "Could not update the case.",
      };
    }
  },
});

export const setAccountStatus = mutation({
  args: {
    accountId: v.string(),
    status: v.string(),
    note: v.optional(v.string()),
    actor: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    try {
      const account = await ctx.db
        .query("accounts")
        .withIndex("by_accountId", (q) => q.eq("accountId", args.accountId))
        .unique();
      if (!account) return { ok: false, error: `Account ${args.accountId} not found.` };

      const allowed = ["NORMAL", "SUSPICIOUS", "MULE_SUSPECT", "BLOCKED", "UNDER_REVIEW", "CLEARED"];
      const status = allowed.includes(args.status) ? args.status : "UNDER_REVIEW";
      const now = Date.now();

      await ctx.db.patch(account._id, {
        status: status as never,
        isMuleSuspect: status === "MULE_SUSPECT" || status === "BLOCKED",
        riskLevel:
          status === "BLOCKED" || status === "MULE_SUSPECT"
            ? "HIGH"
            : status === "CLEARED"
              ? "LOW"
              : account.riskLevel,
      });

      // Keep the graph sub-view consistent without a full recompute.
      if (status === "BLOCKED" || status === "CLEARED") {
        const rows = await ctx.db.query("fraudCases").take(200);
        const related = rows.filter((row) => row.beneficiaryId === args.accountId);
        for (const row of related.slice(0, 25)) {
          if (status === "BLOCKED" && row.status !== "RESOLVED") {
            await ctx.db.patch(row._id, {
              status: "ESCALATED",
              updatedAt: now,
              timeline: [
                ...row.timeline,
                {
                  at: now,
                  actor: args.actor ?? "analyst",
                  action: "BENEFICIARY_BLOCKED",
                  note: args.note?.trim() || `Beneficiary ${account.name} blocked from settlement.`,
                },
              ],
            });
          }
        }
      }

      await ctx.db.insert("auditLogs", {
        logId: `LOG-${nonceFor(["account", args.accountId, now]).slice(0, 10)}`,
        actor: args.actor ?? "analyst",
        action: `ACCOUNT_${status}`,
        entityType: "account",
        entityId: args.accountId,
        timestamp: now,
        details:
          args.note?.trim() ||
          `${account.name} (${account.upiId}) marked ${status} by the fraud analyst console.`,
      });

      return { ok: true, error: null, status };
    } catch (error) {
      return {
        ok: false,
        error: error instanceof Error ? error.message : "Could not update the account.",
      };
    }
  },
});

export const registerMerchant = mutation({
  args: {
    merchantName: v.string(),
    category: v.string(),
    city: v.string(),
    actor: v.optional(v.string()),
  },
  handler: async (ctx, args) => {
    try {
      const name = (args.merchantName ?? "").trim();
      if (name.length < 3) {
        return { ok: false, error: "Merchant name must be at least 3 characters.", merchantId: null };
      }
      const rows = await ctx.db.query("merchants").take(200);
      const merchantId = `MER${String(rows.length + 1).padStart(4, "0")}`;
      const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, "").slice(0, 16) || "merchant";
      const upiId = `${slug}${String(rows.length + 1).padStart(3, "0")}@merchant`;
      const now = Date.now();

      await ctx.db.insert("merchants", {
        merchantId,
        merchantName: name,
        upiId,
        category: args.category || "Retail",
        city: args.city || "Mumbai",
        isVerified: true,
        qrSecretVersion: 1,
        status: "ACTIVE",
        registeredAt: now,
        totalQrCodes: 0,
        flaggedCount: 0,
      });

      await ctx.db.insert("accounts", {
        accountId: merchantId,
        name,
        upiId,
        kind: "MERCHANT",
        createdAt: now,
        accountAgeDays: 0,
        riskLevel: "LOW",
        isMuleSuspect: false,
        status: "NORMAL",
        category: args.category || "Retail",
        city: args.city || "Mumbai",
        isVerified: true,
        inDegree: 0,
        outDegree: 0,
        totalReceived: 0,
        totalSent: 0,
        outflowRatio: 0,
        uniqueSenders: 0,
        uniqueReceivers: 0,
        avgReceiveToSendSec: 86400,
        clustering: 0,
        community: 900,
        riskScore: 5,
        flaggedReasons: [],
      });

      const metricsRow = await ctx.db
        .query("dashMetrics")
        .withIndex("by_key", (q) => q.eq("key", "global"))
        .unique();
      if (metricsRow) {
        await ctx.db.patch(metricsRow._id, {
          verifiedMerchants: metricsRow.verifiedMerchants + 1,
        });
      }

      await ctx.db.insert("auditLogs", {
        logId: `LOG-${nonceFor(["merchant", merchantId]).slice(0, 10)}`,
        actor: args.actor ?? "analyst",
        action: "MERCHANT_REGISTERED",
        entityType: "merchant",
        entityId: merchantId,
        timestamp: now,
        details: `${name} registered (${upiId}) in category ${args.category || "Retail"}.`,
      });

      return { ok: true, error: null, merchantId, upiId };
    } catch (error) {
      return {
        ok: false,
        error: error instanceof Error ? error.message : "Could not register the merchant.",
        merchantId: null,
      };
    }
  },
});

export const accountDetail = query({
  args: { accountId: v.string() },
  handler: async (ctx, args) => {
    try {
      const account = await ctx.db
        .query("accounts")
        .withIndex("by_accountId", (q) => q.eq("accountId", args.accountId))
        .unique();
      if (!account) return { ok: false, account: null, transactions: [], cases: [], audit: [] };

      const transactions = await ctx.db
        .query("transactions")
        .withIndex("by_beneficiaryId", (q) => q.eq("beneficiaryId", args.accountId))
        .order("desc")
        .take(20);
      const cases = await ctx.db
        .query("fraudCases")
        .withIndex("by_txnId", (q) => q.eq("txnId", transactions[0]?.txnId ?? "__none__"))
        .take(1);
      const audit = await ctx.db
        .query("auditLogs")
        .withIndex("by_entityId", (q) => q.eq("entityId", args.accountId))
        .take(20);

      return {
        ok: true,
        account,
        transactions: transactions.map((txn) => ({
          txnId: txn.txnId,
          amount: txn.amount,
          timestamp: txn.timestamp,
          userName: txn.userName,
          diamondTrustScore: txn.diamondTrustScore,
          isFraudLabel: txn.isFraudLabel,
        })),
        cases,
        audit,
      };
    } catch {
      return { ok: false, account: null, transactions: [], cases: [], audit: [] };
    }
  },
});

/** Top suspicious beneficiaries + QR registry health for the overview page. */
export const overviewExtras = query({
  args: {},
  handler: async (ctx) => {
    try {
      const qrRows = await ctx.db.query("qrCodes").take(400);
      const byStatus = qrRows.reduce<Record<string, number>>((acc, row) => {
        acc[row.status] = (acc[row.status] ?? 0) + 1;
        return acc;
      }, {});
      const tampered = qrRows
        .filter((row) => row.status === "TAMPERED")
        .slice(0, 6)
        .map((row) => ({
          qrId: row.qrId,
          merchantName: row.merchantName,
          tamperMode: row.tamperMode ?? "unknown",
          createdAt: row.createdAt,
        }));
      return { ok: true, byStatus, tampered };
    } catch {
      return { ok: false, byStatus: {}, tampered: [] };
    }
  },
});
